import 'dart:convert';import 'package:flutter/material.dart';import '../../../core/data/astro_repository.dart';import '../../../core/data/local_database.dart';import '../../../core/models/reading.dart';import '../../../core/models/zodiac_sign.dart';import '../../../shared/widgets/app_components.dart';
class PeriodReadingsScreen extends StatefulWidget{const PeriodReadingsScreen({super.key});@override State<PeriodReadingsScreen> createState()=>_PeriodReadingsScreenState();}
class _PeriodReadingsScreenState extends State<PeriodReadingsScreen>{String period='weekly',sign='aries',category='general';List<HoroscopeReading> rows=[];List<String> enabledCategories=['general','love','career','wellbeing'];@override void initState(){super.initState();_load();}
Future<void> _load()async{sign=await AstroRepository.instance.selectedSign();enabledCategories=await AstroRepository.instance.enabledCategories();if(!enabledCategories.contains(category))category=enabledCategories.first;final db=await LocalDatabase.instance.database;final cache=await db.query('content_cache');final out=<HoroscopeReading>[];for(final item in cache){try{final doc=jsonDecode(item['payload'] as String);if(doc is Map&&doc['readings'] is List){for(final raw in doc['readings']){out.add(HoroscopeReading.fromJson(Map<String,dynamic>.from(raw)));}}}catch(_){}}if(mounted)setState(()=>rows=out);}
@override Widget build(BuildContext context){final list=rows.where((r)=>r.signId==sign&&r.periodType==period&&r.category==category&&r.status=='published').toList()..sort((a,b)=>b.periodStart.compareTo(a.periodStart));return Scaffold(appBar:AppBar(title:const Text('Weekly & monthly readings')),body:ListView(padding:const EdgeInsets.all(20),children:[const PageHeader('A wider perspective',subtitle:'Coverage dates are shown exactly as published.'),SegmentedButton<String>(segments:const[ButtonSegment(value:'weekly',label:Text('Weekly')),ButtonSegment(value:'monthly',label:Text('Monthly'))],selected:{period},onSelectionChanged:(v)=>setState(()=>period=v.first)),const SizedBox(height:14),Wrap(spacing:6,children:enabledCategories.map((c)=>ChoiceChip(label:Text(c),selected:category==c,onSelected:(_)=>setState(()=>category=c))).toList()),if(list.isEmpty)const InfoCard('No published reading pack is available for this period and category yet. AstroDaily will not substitute an older or invented reading.'),for(final r in list)Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(r.title,style:Theme.of(context).textTheme.titleLarge),Text(r.periodStart+' – '+r.periodEnd,style:const TextStyle(color:Colors.grey)),const SizedBox(height:8),Text(r.body),TextButton(onPressed:()=>AstroRepository.instance.toggleSaved({'id':r.id,'sign':r.signId,'title':r.title,'body':r.body,'prompt':r.prompt}),child:const Text('Save reading'))]))),const DisclaimerCard()]));}
}
